class Store:
    def __init__(self):
        self.state = {"count": 0, "log": []}
        self.history = []

    def increment(self):
        self.history.append(self.state)
        self.state["count"] += 1
        self.state["log"].append("+1")

    def undo(self):
        if self.history:
            self.state = self.history.pop()


store = Store()
for _ in range(int(input())):
    store.increment()
for _ in range(int(input())):
    store.undo()
print(store.state["count"], store.state["log"])

